#include <stdio.h>

int main() {
    int N, case_num = 1;

    while (scanf("%d", &N) == 1 && N != 0) {
        int matrix[10][10]; // N <= 10 as per typical constraints

        // Fill the matrix with zigzag traversal order
        int num = 1;
        for (int sum = 0; sum <= 2 * (N - 1); sum++) {
            if (sum % 2 == 0) { // Even sum: bottom-left to top-right
                for (int i = (sum < N) ? sum : N - 1; i >= 0; i--) {
                    int j = sum - i;
                    if (j >= 0 && j < N) {
                        matrix[i][j] = num++;
                    }
                }
            } else { // Odd sum: top-left to bottom-right
                for (int j = (sum < N) ? sum : N - 1; j >= 0; j--) {
                    int i = sum - j;
                    if (i >= 0 && i < N) {
                        matrix[i][j] = num++;
                    }
                }
            }
        }

        // Print the matrix with header
        printf("Case %d:\n", case_num++);
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                printf("%3d", matrix[i][j]);
            }
            printf("\n");
        }
    }

    return 0;
}

