int main() {
    int t = 1;
    int N;
    while (cin >> N) {
        vector<vector<int>> matrix(N, vector<int>(N));
        int r = 0, c = 0;
        int dir = 1; // 1 = down-left, -1 = up-right
        for (int i = 1; i <= N * N; ++i) {
            matrix[r][c] = i;
            if (dir == 1) {
                if (r + 1 < N && c - 1 >= 0) {
                    r++;
                    c--;
                } else if (r + 1 < N) {
                    r++;
                    dir = -1;
                } else {
                    c++;
                    dir = -1;
                }
            } else {
                if (r - 1 >= 0 && c + 1 < N) {
                    r--;
                    c++;
                } else if (c + 1 < N) {
                    c++;
                    dir = 1;
                } else {
                    r++;
                    dir = 1;
                }
            }
        }

        cout << "Case " << t++ << ":" << endl;
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                cout << setw(3) << matrix[i][j];
            }
            cout << endl;
        }
    }
    return 0;
}

