import java.util.Scanner;

public class ZigzagTraversal {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();

        for (int caseNum = 1; caseNum <= t; caseNum++) {
            int N = sc.nextInt();
            int[][] matrix = new int[N][N];

            int row = 0, col = 0;
            boolean goingUp = true;

            for (int i = 1; i <= N * N; i++) {
                matrix[row][col] = i;

                if (goingUp) {
                    if (col == N - 1) {
                        row++;
                        goingUp = false;
                    } else if (row == 0) {
                        col++;
                        goingUp = false;
                    } else {
                        row--;
                        col++;
                    }
                } else {
                    if (row == N - 1) {
                        col++;
                        goingUp = true;
                    } else if (col == 0) {
                        row++;
                        goingUp = true;
                    } else {
                        row++;
                        col--;
                    }
                }
            }

            System.out.println("Case #" + caseNum + ":");
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    System.out.printf("%3d", matrix[i][j]);
                }
                System.out.println();
            }
        }
        sc.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int caseNum = 1;
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            int[][] matrix = new int[n][n];
            int count = 1;

            for (int d = 0; d < 2 * n - 1; d++) {
                int rowStart, rowEnd;
                rowStart = Math.max(0, d - n + 1);
                rowEnd = Math.min(d, n - 1);

                if (d % 2 == 0) {
                    // row increases from rowStart to rowEnd
                    for (int r = rowStart; r <= rowEnd; r++) {
                        int c = d - r;
                        matrix[r][c] = count++;
                    }
                } else {
                    // row decreases from rowEnd to rowStart
                    for (int r = rowEnd; r >= rowStart; r--) {
                        int c = d - r;
                        matrix[r][c] = count++;
                    }
                }
            }

            System.out.println("Case #" + caseNum++);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    System.out.printf("%3d", matrix[i][j]);
                }
                System.out.println();
            }
        }
        sc.close();
    }
}

