import sys

def zigzag_matrix(n: int):
    a = [[0] * n for _ in range(n)]
    num = 1

    for s in range(2 * n - 1):
        cells = []
        r_start = max(0, s - (n - 1))
        r_end = min(n - 1, s)
        for r in range(r_start, r_end + 1):
            c = s - r
            cells.append((r, c))

        if s % 2 == 0:
            cells.reverse()

        for r, c in cells:
            a[r][c] = num
            num += 1

    return a

def main():
    data = sys.stdin.read().strip().split()
