    nums = list(map(int, data))
    out = []
    case_no = 1

    for n in nums:
        if n == 0:
            break

        mat = zigzag_matrix(n)
        out.append(f"Case {case_no}:")
        for row in mat:
            out.append("".join(f"{x:>3}" for x in row))
        case_no += 1

    sys.stdout.write("\n".join(out))

